function SetMinSum(uint _val)
    public
    {
        if(intitalized)revert();
        require(_val >= 1 ether, "MinSum too low");
        MinSum = _val;
    }

function SetMinSum(uint _val)
    public
    {
        if(intitalized)revert();
        MinSum = MinSum + _val;
    }

function SetMinSum(uint _val)
    public
    {
        if(intitalized)revert();
        MinSum = MinSum - _val;
    }

function SetMinSum(uint _val)
    public
    {
        if(intitalized)revert();
        MinSum = uint(-int(_val));
    }

